static const size_t g_logo_sz = sizeof(g_logo);

static const int WW=640, WH=720, SW=188, HH=46;

static HANDLE    g_proc  = nullptr;
static uintptr_t g_base  = 0;
static HWND      g_hwnd  = nullptr;
static HWND      g_esp   = nullptr;
static std::atomic<bool> g_run{true};
static std::atomic<int>  g_ec{0};
static Image*    g_logo_img = nullptr;
static DWORD     g_pid   = 0;

template<typename T>
static T RPM(uintptr_t a){T v{};ReadProcessMemory(g_proc,(LPCVOID)a,&v,sizeof(T),nullptr);return v;}
template<typename T>
static void WPM(uintptr_t a,T v){WriteProcessMemory(g_proc,(LPVOID)a,&v,sizeof(T),nullptr);}

namespace Ptr{
    constexpr uintptr_t TS=0x08E4D7B8ULL, FDM=0x08EB6960ULL, VE=0x08942E38ULL;
}
namespace Off{
    constexpr uintptr_t FDM_R=504, DM_WS=328, PL_LP=280;
    constexpr uintptr_t P_Mod=672, I_NB=104, I_CB=112, I_CE=120;
    constexpr uintptr_t H_HP=388, H_MHP=396, H_HRP=1120, H_Jmp=464;
    constexpr uintptr_t BP_Pr=376, PR_Pos=212;
    constexpr uintptr_t VE_VM=432, VE_Dim=2832, TS_FPS=176, SL=16;
}

struct V2{float x=0,y=0;};
struct V3{float x=0,y=0,z=0;};

struct Cfg {
    bool  aOn=false;  float aFov=250, aSm=30;
    bool  aNs=false, aKc=false, aNp=false;  int aBone=0;
    bool  sOn=false;  float sFov=100, sPx=0.165f, sPy=0.165f;  bool sPr=false;
    bool  tOn=false;  int tTy=0;  float tSd=0, tRd=50;
    bool  tHo=false, tTc=true, tBu=false;  float tBs=3;
    bool  eOn=false;  int eBx=1;
    bool  eSk=false, eNm=true, eDi=false, eHb=false;
    float eDst=200;
    bool  eTc=true, eNpc=false, eHc=true;
    bool  mBh=false, mFl=false, mSh=false;
    float mFla=6, mSm=1.5f, mFps=60;
    bool  bOn=true;                 // blacklist enabled
    bool  sSp=false, sVs=false;     // settings: streamproof, vsync
} cfg;

struct EnemyInfo {
    V3    pos;
    float hp=0, maxhp=100;
    std::string name;
    V2    sk[7];
    bool  skv[7]={};
    V2    scr;
    bool  scrv=false;
    float dist=0;
};
static std::vector<EnemyInfo> g_enemies;
static CRITICAL_SECTION g_cs;

static const char* BONE_PARTS[] = {
    "Head","UpperTorso","LowerTorso",
    "LeftUpperArm","RightUpperArm",
    "LeftUpperLeg","RightUpperLeg"
};

static std::string RStr(uintptr_t b){
    size_t l=RPM<size_t>(b+Off::SL); if(!l||l>512)return{};
    char buf[512]={};
    if(l<16) ReadProcessMemory(g_proc,(LPCVOID)b,buf,l,nullptr);
    else{uintptr_t p=RPM<uintptr_t>(b);if(p)ReadProcessMemory(g_proc,(LPCVOID)p,buf,l,nullptr);}
    return{buf,l};
}
static std::vector<uintptr_t> Kids(uintptr_t i){
    uintptr_t b=RPM<uintptr_t>(i+Off::I_CB), e=RPM<uintptr_t>(i+Off::I_CE);
    if(!b||e<=b||(e-b)>0x8000)return{};
    std::vector<uintptr_t> v((e-b)/8);
    ReadProcessMemory(g_proc,(LPCVOID)b,v.data(),(e-b),nullptr); return v;
}
static uintptr_t Kid(uintptr_t i,const char*n){
    for(auto c:Kids(i)) if(c&&RStr(c+Off::I_NB)==n)return c; return 0;
}
static uintptr_t GetDM(){
    uintptr_t f=RPM<uintptr_t>(g_base+Ptr::FDM); return f?RPM<uintptr_t>(f+Off::FDM_R):0;
}
static bool W2S(V3 w, V2& s){
    uintptr_t ve=RPM<uintptr_t>(g_base+Ptr::VE); if(!ve)return false;
    float m[16],d[2];
    ReadProcessMemory(g_proc,(LPCVOID)(ve+Off::VE_VM),m,64,nullptr);
    ReadProcessMemory(g_proc,(LPCVOID)(ve+Off::VE_Dim),d,8,nullptr);
    if(d[0]<1||d[1]<1)return false;
    float x=w.x*m[0]+w.y*m[4]+w.z*m[8]+m[12];
    float y=w.x*m[1]+w.y*m[5]+w.z*m[9]+m[13];
    float ww=w.x*m[3]+w.y*m[7]+w.z*m[11]+m[15];
    if(ww<0.1f)return false;
    s.x=(x/ww*.5f+.5f)*d[0]; s.y=(-y/ww*.5f+.5f)*d[1]; return true;
}

static DWORD GetPID(const char*n){
    HANDLE h=CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS,0);
    if(h==INVALID_HANDLE_VALUE)return 0;
    PROCESSENTRY32 pe{};pe.dwSize=sizeof(pe);DWORD r=0;
    if(Process32First(h,&pe))
        do{if(!_stricmp(pe.szExeFile,n)){r=pe.th32ProcessID;break;}}while(Process32Next(h,&pe));
    CloseHandle(h);return r;
}
static uintptr_t GetBase(DWORD pid,const char*n){
    HANDLE h=CreateToolhelp32Snapshot(TH32CS_SNAPMODULE|TH32CS_SNAPMODULE32,pid);
    if(h==INVALID_HANDLE_VALUE)return 0;
    MODULEENTRY32 me{};me.dwSize=sizeof(me);uintptr_t b=0;
    if(Module32First(h,&me))
        do{if(!_stricmp(me.szModule,n)){b=(uintptr_t)me.modBaseAddr;break;}}while(Module32Next(h,&me));
    CloseHandle(h);return b;
}

static std::wstring CfgPath(){
    wchar_t buf[MAX_PATH];
    GetEnvironmentVariableW(L"APPDATA",buf,MAX_PATH);
    return std::wstring(buf)+L"\\aurora.cfg";
}
static void SaveCfg(){
    std::ofstream f(CfgPath(),std::ios::binary);
    if(f) f.write((char*)&cfg,sizeof(cfg));
}
static void LoadCfg(){
    std::ifstream f(CfgPath(),std::ios::binary);
    if(f) f.read((char*)&cfg,sizeof(cfg));
}

// ---- blacklist (names skipped by ESP / aimbot / triggerbot) — guarded by g_cs
static std::vector<std::string> g_bl;
static std::wstring BlPath(){
    wchar_t buf[MAX_PATH];
    GetEnvironmentVariableW(L"APPDATA",buf,MAX_PATH);
    return std::wstring(buf)+L"\\aurora_blacklist.txt";
}
static bool IsBL(const std::string&n){
    bool r=false;
    EnterCriticalSection(&g_cs);
    for(auto&x:g_bl)if(x==n){r=true;break;}
    LeaveCriticalSection(&g_cs);
    return r;
}
static size_t BlCount(){
    EnterCriticalSection(&g_cs);size_t n=g_bl.size();LeaveCriticalSection(&g_cs);return n;
}
static void SaveBL(){
    EnterCriticalSection(&g_cs);
    std::ofstream f(BlPath(),std::ios::binary|std::ios::trunc);
    if(f)for(auto&x:g_bl)f<<x<<"\n";
    LeaveCriticalSection(&g_cs);
}
static void LoadBL(){
    std::ifstream f(BlPath(),std::ios::binary);
    std::string ln;
    EnterCriticalSection(&g_cs);
    g_bl.clear();
    while(std::getline(f,ln)){
        while(!ln.empty()&&(ln.back()=='\r'||ln.back()=='\n'))ln.pop_back();
        if(!ln.empty())g_bl.push_back(ln);
    }
    LeaveCriticalSection(&g_cs);
}

// streamproof = hide both windows from screen capture (Win10 2004+)
static void ApplySettings(){
    DWORD a=cfg.sSp?WDA_EXCLUDEFROMCAPTURE:WDA_NONE;
    if(g_hwnd)SetWindowDisplayAffinity(g_hwnd,a);
    if(g_esp) SetWindowDisplayAffinity(g_esp,a);
}

static std::atomic<bool> g_gui_visible{true};

static void Logic(){
    bool ins_prev=false, f4_prev=false;
    ULONGLONG f4_last=0;
    while(g_run){
        std::this_thread::sleep_for(1ms);

        // INSERT — toggle GUI visibility
        bool ins_now=(GetAsyncKeyState(VK_INSERT)&0x8000)!=0;
        if(ins_now && !ins_prev){
            g_gui_visible=!g_gui_visible;
            if(g_hwnd)
                ShowWindow(g_hwnd, g_gui_visible ? SW_SHOWNOACTIVATE : SW_HIDE);
        }
        ins_prev=ins_now;

        // F4 x2 within 400ms — close AURORA (single press does nothing)
        bool f4_now=(GetAsyncKeyState(VK_F4)&0x8000)!=0;
        if(f4_now && !f4_prev){
            ULONGLONG t=GetTickCount64();
            if(f4_last && t-f4_last<=400){
                f4_last=0;
                if(g_hwnd)PostMessageW(g_hwnd,WM_CLOSE,0,0);
            }else f4_last=t;
        }
        f4_prev=f4_now;

        uintptr_t dm=GetDM();if(!dm)continue;
        uintptr_t ws=RPM<uintptr_t>(dm+Off::DM_WS);if(!ws)continue;
        uintptr_t pl=Kid(dm,"Players");if(!pl)continue;
        uintptr_t lp=RPM<uintptr_t>(pl+Off::PL_LP);if(!lp)continue;

        std::vector<EnemyInfo> ens;
        for(auto ch:Kids(pl)){
            if(!ch||ch==lp)continue;
            uintptr_t chr=RPM<uintptr_t>(ch+Off::P_Mod);if(!chr)continue;
            uintptr_t hum=Kid(chr,"Humanoid");if(!hum)continue;
            float hp=RPM<float>(hum+Off::H_HP);
            if(hp<=0)continue;
            float mhp=RPM<float>(hum+Off::H_MHP);
            if(cfg.eHc && hp<1)continue;
            uintptr_t hrp=RPM<uintptr_t>(hum+Off::H_HRP);if(!hrp)continue;
            uintptr_t pr=RPM<uintptr_t>(hrp+Off::BP_Pr);if(!pr)continue;
            EnemyInfo ei;
            ei.pos=RPM<V3>(pr+Off::PR_Pos);
            ei.hp=hp; ei.maxhp=(mhp>0?mhp:100.f);
            ei.name=RStr(ch+Off::I_NB);
            if(cfg.bOn&&IsBL(ei.name))continue;
            for(int b=0;b<7;b++){
                uintptr_t part=Kid(chr,BONE_PARTS[b]);
                if(part){
                    uintptr_t bpr=RPM<uintptr_t>(part+Off::BP_Pr);
                    if(bpr){V3 wp=RPM<V3>(bpr+Off::PR_Pos);ei.skv[b]=W2S(wp,ei.sk[b]);}
                }
            }
            ei.scrv=W2S(ei.pos,ei.scr);
            ens.push_back(ei);
        }
        g_ec.store((int)ens.size());
        EnterCriticalSection(&g_cs);
        g_enemies=ens;
        LeaveCriticalSection(&g_cs);
        if(g_esp&&cfg.eOn) InvalidateRect(g_esp,nullptr,FALSE);
        if(cfg.sVs) DwmFlush();     // vsync: loop locks to DWM refresh (also paces aimbot)

        float cx=GetSystemMetrics(SM_CXSCREEN)*.5f, cy=GetSystemMetrics(SM_CYSCREEN)*.5f;

        if(cfg.aOn&&(GetAsyncKeyState(VK_RBUTTON)&0x8000)){
            EnemyInfo*best=nullptr; float bd=cfg.aFov;
            for(auto&e:ens){if(!e.scrv)continue;float d=std::hypotf(e.scr.x-cx,e.scr.y-cy);if(d<bd){bd=d;best=&e;}}
            if(best&&best->scrv){
                float sm=(std::max)(1.f,cfg.aSm/10.f);
                INPUT in{};in.type=INPUT_MOUSE;in.mi.dwFlags=MOUSEEVENTF_MOVE;
                in.mi.dx=(int)((best->scr.x-cx)/sm);in.mi.dy=(int)((best->scr.y-cy)/sm);
                SendInput(1,&in,sizeof(in));
            }
        }
        if(cfg.tOn){
            bool fire=false;
            for(auto&e:ens){if(!e.scrv)continue;if(std::hypotf(e.scr.x-cx,e.scr.y-cy)<15.f){fire=true;break;}}
            if(fire){
                std::this_thread::sleep_for(std::chrono::milliseconds((int)cfg.tSd));
                INPUT in{};in.type=INPUT_MOUSE;in.mi.dwFlags=MOUSEEVENTF_LEFTDOWN;SendInput(1,&in,sizeof(in));
                std::this_thread::sleep_for(std::chrono::milliseconds((int)cfg.tRd));
                in.mi.dwFlags=MOUSEEVENTF_LEFTUP;SendInput(1,&in,sizeof(in));
            }
        }
        if(cfg.mBh){
            uintptr_t chr=RPM<uintptr_t>(lp+Off::P_Mod);
            if(chr){uintptr_t h=Kid(chr,"Humanoid");
                if(h&&(GetAsyncKeyState(VK_SPACE)&0x8000))WPM<uint8_t>(h+Off::H_Jmp,1);}
        }
        {uintptr_t ts=RPM<uintptr_t>(g_base+Ptr::TS);if(ts)WPM<double>(ts+Off::TS_FPS,(double)cfg.mFps);}
    }
}

// ESP overlay
static void DrawESP(HDC hdc){
    Graphics g(hdc);
    g.SetSmoothingMode(SmoothingModeAntiAlias);
    Pen pBox(Color(255,0,200,255),1.5f);
    Pen pSkel(Color(255,255,220,0),1.2f);

    std::vector<EnemyInfo> snap;
    EnterCriticalSection(&g_cs);
    snap=g_enemies;
    LeaveCriticalSection(&g_cs);

    for(auto&e:snap){
        if(!e.scrv||!e.skv[0])continue;
        float top=e.sk[0].y;
        float bot=top+120;
        if(e.skv[5]||e.skv[6]) bot=(std::max)(e.skv[5]?e.sk[5].y:0.f,e.skv[6]?e.sk[6].y:0.f)+20;
        float h=bot-top; float w=h*0.5f;
        float left=e.scr.x-w*0.5f;

        if(cfg.eBx==1){
            g.DrawRectangle(&pBox,left,top,w,h);
        } else if(cfg.eBx==2){
            float ox=w*0.15f,oy=h*0.05f;
            g.DrawRectangle(&pBox,left,top,w,h);
            g.DrawRectangle(&pBox,left+ox,top-oy,w,h);
            g.DrawLine(&pBox,left,top,left+ox,top-oy);
            g.DrawLine(&pBox,left+w,top,left+w+ox,top-oy);
            g.DrawLine(&pBox,left,top+h,left+ox,top+h-oy);
            g.DrawLine(&pBox,left+w,top+h,left+w+ox,top+h-oy);
        } else if(cfg.eBx==3){
            float cl=w*0.25f,cs=h*0.12f;
            g.DrawLine(&pBox,left,top,left+cl,top);       g.DrawLine(&pBox,left,top,left,top+cs);
            g.DrawLine(&pBox,left+w,top,left+w-cl,top);   g.DrawLine(&pBox,left+w,top,left+w,top+cs);
            g.DrawLine(&pBox,left,top+h,left+cl,top+h);   g.DrawLine(&pBox,left,top+h,left,top+h-cs);
            g.DrawLine(&pBox,left+w,top+h,left+w-cl,top+h);g.DrawLine(&pBox,left+w,top+h,left+w,top+h-cs);
        }

        if(cfg.eHb){
            float ratio=(std::max)(0.f,(std::min)(1.f,e.hp/e.maxhp));
            float bh2=h*ratio;
            SolidBrush bg(Color(140,10,10,10));
            g.FillRectangle(&bg,RectF(left-7,top,4,h));
            Color hc((BYTE)(255*(1.f-ratio)),(BYTE)(255*ratio),50);
            SolidBrush hpb(hc);
            g.FillRectangle(&hpb,RectF(left-7,top+h-bh2,4,bh2));
        }

        if(cfg.eSk){
            static const int LIMBS[][2]={{0,1},{1,2},{2,3},{2,4},{2,5},{2,6}};
            for(auto&lmb:LIMBS){
                if(e.skv[lmb[0]]&&e.skv[lmb[1]])
                    g.DrawLine(&pSkel,e.sk[lmb[0]].x,e.sk[lmb[0]].y,e.sk[lmb[1]].x,e.sk[lmb[1]].y);
            }
        }

        if(cfg.eNm){
            static FontFamily ff(L"Segoe UI");
            static Font fnt(&ff,9,FontStyleRegular,UnitPoint);
            SolidBrush tb(Color(255,255,255,255));
            StringFormat sf;sf.SetAlignment(StringAlignmentCenter);
            std::wstring wn(e.name.begin(),e.name.end());
            g.DrawString(wn.c_str(),-1,&fnt,RectF(e.scr.x-60,top-18,120,18),&sf,&tb);
        }

        if(cfg.eDi){
            static FontFamily ff(L"Segoe UI");
            static Font fnt(&ff,8,FontStyleRegular,UnitPoint);
            SolidBrush tb(Color(255,160,160,160));
            StringFormat sf;sf.SetAlignment(StringAlignmentCenter);
            wchar_t db[32];swprintf(db,32,L"%.0fm",e.dist/50.f);
            g.DrawString(db,-1,&fnt,RectF(e.scr.x-40,bot+4,80,16),&sf,&tb);
        }
    }
}

LRESULT CALLBACK ESPProc(HWND hw,UINT msg,WPARAM wp,LPARAM lp){
    if(msg==WM_PAINT){
        PAINTSTRUCT ps;HDC hdc=BeginPaint(hw,&ps);
        int sw=GetSystemMetrics(SM_CXSCREEN),sh=GetSystemMetrics(SM_CYSCREEN);
        RECT rc{0,0,sw,sh};FillRect(hdc,&rc,(HBRUSH)GetStockObject(BLACK_BRUSH));
        if(cfg.eOn)DrawESP(hdc);
        EndPaint(hw,&ps);return 0;
    }
    if(msg==WM_TIMER){InvalidateRect(hw,nullptr,FALSE);return 0;}
    return DefWindowProc(hw,msg,wp,lp);
}

